#!/usr/bin/env node
// Concatenate the portable core and the add-on adapter into one Apps
// Script file. Apps Script gives each file its own scope for const/let,
// so the core's `const FlowJudgment` would be invisible to intent.js if
// the files were pushed separately. One file keeps the Chrome load order.

const fs = require('fs');
const path = require('path');

const repo = path.join(__dirname, '..', '..');
const core = path.join(repo, 'flow-trial-extension', 'core');
const src = path.join(__dirname, '..', 'src');
const out = path.join(__dirname, '..', 'CoreBundle.js');

const files = [
  'domains.js',
  'extract.js',
  'judgment.js',
  'google-closes.js',
  'close-families.js',
  'fact-reply.js',
  'file-attach.js',
  'intent.js',
  'actions.js'
].map((name) => path.join(core, name)).concat([
  path.join(repo, 'flow-trial-extension', 'src', 'receipt-copy.js'),
  path.join(src, 'payloads.js'),
  path.join(src, 'decide.js')
]);

const header = [
  '// Generated by glance-gmail-addon/scripts/build-bundle.js.',
  '// Do not edit. Re-run the script after changing the core or src/.',
  '// Apps Script runs this file on Google\'s servers. It does not send',
  '// the message to Flow, and it has no send path.',
  ''
].join('\n');

const footer = [
  '',
  'var Glance = {',
  '  decide: GlanceDecide.decide,',
  '  quietEn: GlanceDecide.QUIET_EN,',
  '  quietHe: GlanceDecide.QUIET_HE,',
  '  receipt: FlowReceipt,',
  '  payloads: GlancePayloads',
  '};',
  ''
].join('\n');

const parts = files.map((file) => {
  return '// ----- ' + path.relative(repo, file) + ' -----\n' + fs.readFileSync(file, 'utf8').replace(/\s+$/, '') + '\n';
});

fs.writeFileSync(out, header + parts.join('\n') + footer);
console.log('wrote ' + path.relative(repo, out) + ' (' + files.length + ' sources)');
